// Kernel: max_reduce_kernel
// Reduces a 3‑D tensor over a specified dimension using fp16 max.
// Arguments:
//   .param .u64 x_ptr        // input pointer (fp16)
//   .param .u64 out_ptr      // output pointer (fp16)
//   .param .u32 batch        // size of dimension 0
//   .param .u32 dim0         // size of dimension 0 (same as batch)
//   .param .u32 dim1         // size of dimension 1
//   .param .u32 dim2         // size of dimension 2
//   .param .u32 reduce_dim   // dimension to reduce over (0,1,2)
