//       reference model uses reduce_dim == 1.
.visible .entry max_reduce_kernel(
    .param .u64 x_ptr,
    .param .u64 out_ptr,
    .param .u32 batch,
    .param .u32 dim0,
    .param .u32 dim1,
    .param .u32 dim2,
    .param .u32 reduce_dim
)
