    // Load parameters
    // ------------------------------
    .reg .u64 %x_ptr, %out_ptr;
    .reg .u32 %batch, %dim0, %dim1, %dim2, %reduce_dim;
    ld.param.u64 %x_ptr,    [x_ptr];
    ld.param.u64 %out_ptr,  [out_ptr];
    ld.param.u32 %batch,    [batch];
    ld.param.u32 %dim0,     [dim0];
    ld.param.u32 %dim1,     [dim1];
    ld.param.u32 %dim2,     [dim2];
    ld.param.u32 %reduce_dim,[reduce_dim];

    // ------------------------------
    // Thread identifiers
    // ------------------------------
    .reg .u32 %tid_x, %block_x, %idx;
    mov.u32 %tid_x,   %tid.x;      // threadIdx.x
    mov.u32 %block_x, %ctaid.x;    // blockIdx.x
    mad.lo.u32 %idx, %block_x, %ntid.x, %tid_x; // linear thread id

    // ------------------------------
    // Compute total number of output elements
    // ------------------------------
    // Output dimensions are the input dimensions with the reduction dimension removed.
    .reg .u32 %out_dim0, %out_dim1, %out_total;
    // Determine output shape based on reduce_dim
    // For simplicity we compute the product of the two kept dims.
    //   keep0 = (reduce_dim == 0) ? dim1 : dim0
    //   keep1 = (reduce_dim == 2) ? dim1 : dim2   (when reduce_dim==1 keep both dim0 and dim2)
    .reg .u32 %keep0, %keep1;
    setp.eq.u32 %p0, %reduce_dim, 0;
    setp.eq.u32 %p1, %reduce_dim, 1;
    setp.eq.u32 %p2, %reduce_dim, 2;

    @%p0 mov.u32 %keep0, %dim1;
    @%p0 mov.u32 %keep1, %dim2;
    @%p1 mov.u32 %keep0, %dim0;
    @%p1 mov.u32 %keep1, %dim2;
    @%p2 mov.u32 %keep0, %dim0;
    @%p2 mov.u32 %keep1, %dim1;

    mul.lo.u32 %out_total, %keep0, %keep1;

    // Guard: if thread id exceeds total output, exit.
    setp.ge.u32 %p_exit, %idx, %out_total;
    @%p_exit bra DONE;

    // ------------------------------
    // Decode output coordinates (i0,i1) based on reduction dimension
    // ------------------------------
    .reg .u32 %i0, %i1, %temp;
    // i0 = idx / keep1
    // i1 = idx % keep1
    div.u32 %i0, %idx, %keep1;
    mul.lo.u32 %temp, %i0, %keep1;
    sub.u32 %i1, %idx, %temp;

