    // Compute the base pointer into the input tensor for the first element of the reduction
    // ------------------------------
    // Input layout is row‑major: offset = ((d0 * dim1) + d1) * dim2 + d2
    // We need to map (i0,i1) back to the three original indices depending on reduce_dim.
    .reg .u32 %in_d0, %in_d1, %in_d2;
    // When reducing over dim 0:
    //   i0 -> d1, i1 -> d2, reduction index iterates over d0
    // When reducing over dim 1:
    //   i0 -> d0, i1 -> d2, reduction index iterates over d1
    // When reducing over dim 2:
    //   i0 -> d0, i1 -> d1, reduction index iterates over d2
    @%p0 {
        // reduce_dim == 0
        mov.u32 %in_d0, 0;          // will be replaced inside the loop
        mov.u32 %in_d1, %i0;
        mov.u32 %in_d2, %i1;
    }
    @%p1 {
        // reduce_dim == 1
        mov.u32 %in_d0, %i0;
        mov.u32 %in_d1, 0;          // loop variable
        mov.u32 %in_d2, %i1;
    }
    @%p2 {
        // reduce_dim == 2
        mov.u32 %in_d0, %i0;
        mov.u32 %in_d1, %i1;
        mov.u32 %in_d2, 0;          // loop variable
    }

