    // base = (in_d0 * dim1 + in_d1) * dim2 + in_d2
    .reg .u64 %base_offset;
    .reg .u32 %tmp32;
    mul.lo.u32 %tmp32, %in_d0, %dim1;      // in_d0 * dim1
    add.u32 %tmp32, %tmp32, %in_d1;       // + in_d1
    mul.lo.u32 %tmp32, %tmp32, %dim2;     // * dim2
    add.u32 %tmp32, %tmp32, %in_d2;       // + in_d2
    cvt.u64.u32 %base_offset, %tmp32;
    // Convert element offset to byte offset (fp16 = 2 bytes)
    shl.b64 %base_offset, %base_offset, 1;

    // ------------------------------
    // Load first element to initialise max
    // ------------------------------
    .reg .f16 %max_val, %val;
    ld.global.nc.f16 %max_val, [%x_ptr + %base_offset];

    // ------------------------------
    // Loop over the reduction dimension
    // ------------------------------
    .reg .u32 %r_idx, %r_limit;
    // Set loop limit = size of reduction dimension
    @%p0 mov.u32 %r_limit, %dim0;
    @%p1 mov.u32 %r_limit, %dim1;
    @%p2 mov.u32 %r_limit, %dim2;

    // Start from 1 because element 0 is already loaded
    mov.u32 %r_idx, 1;

REDUCTION_LOOP:
    setp.ge.u32 %p_done, %r_idx, %r_limit;
    @%p_done bra END_LOOP;

    // Compute offset for current reduction index
    // offset = base_offset + (r_idx * stride) * 2
    // stride depends on which dimension we are reducing:
    //   dim0 stride = dim1 * dim2
    //   dim1 stride = dim2
    //   dim2 stride = 1
    .reg .u64 %stride_bytes, %cur_offset;
    @%p0 {
        // reduce_dim == 0
        // stride = dim1 * dim2
        mul.lo.u32 %tmp32, %dim1, %dim2;
    }
    @%p1 {
        // reduce_dim == 1
        // stride = dim2
        mov.u32 %tmp32, %dim2;
    }
    @%p2 {
        // reduce_dim == 2
        // stride = 1
        mov.u32 %tmp32, 1;
    }
    cvt.u64.u32 %stride_bytes, %tmp32;
    shl.b64 %stride_bytes, %stride_bytes, 1;          // *2 for fp16 size
    cvt.u64.u32 %tmp64, %r_idx;
    mul.lo.u64 %tmp64, %tmp64, %stride_bytes;
    add.u64 %cur_offset, %base_offset, %tmp64;

    // Load value and update max
    ld.global.nc.f16 %val, [%x_ptr + %cur_offset];
    max.f16 %max_val, %max_val, %val;

    // Increment reduction index
    add.u32 %r_idx, %r_idx, 1;
    bra REDUCTION_LOOP;

