    // ------------------------------
    // Store the result
    // ------------------------------
    // Output layout is also row‑major over the kept dimensions:
    // out_offset = i0 * keep1 + i1
    mul.lo.u32 %tmp32, %i0, %keep1;
    add.u32 %tmp32, %tmp32, %i1;
    cvt.u64.u32 %out_offset, %tmp32;
    shl.b64 %out_offset, %out_offset, 1;   // fp16 byte stride
    st.global.f16 [%out_ptr + %out_offset], %max_val;

DONE:
    ret;
}
