# --------------------------------------------------------------
# Python wrapper that loads and launches the PTX kernel.
# --------------------------------------------------------------
import torch
from ptx_harness import ptx_load, ptx_launch

class ModelNew(torch.nn.Module):
    def __init__(self, dim: int):
        super().__init__()
        self.dim = dim
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda and x.dtype == torch.float16
        # Compute output shape by removing the reduced dimension
        out_shape = list(x.shape)
        del out_shape[self.dim]
        out = torch.empty(out_shape, dtype=torch.float16, device='cuda')

        batch = x.shape[0]
        dim0 = x.shape[0]
        dim1 = x.shape[1]
        dim2 = x.shape[2]

        # Total number of output elements
        out_elements = out.numel()
        threads_per_block = 256
        blocks = (out_elements + threads_per_block - 1) // threads_per_block

        ptx_launch(
            self.module,
            "max_reduce_kernel",
            (blocks, 1, 1),                # grid
            (threads_per_block, 1, 1),    # block
            [
                x.data_ptr(),
                out.data_ptr(),
                batch,
                dim0,
                dim1,
                dim2,
                self.dim
            ]
        )
        return out
